#!/usr/bin/env node
/**
 * Turns the long-form copy in `content/seo/*.json` into the generated modules the
 * site imports. Run it after editing any file there:
 *
 *   node scripts/build-seo-content.mjs
 *
 * Files:  product-<slug>.json   -> src/lib/content/product-guides.generated.ts
 *         category-<slug>.json  -> src/lib/content/category-guides.generated.ts
 *         blog-<slug>.json, refresh-<slug>.json
 *                               -> prisma/content-migrations/seo-posts.generated.ts
 *
 * The generated files are committed, so a build never needs this script.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const dir = new URL("../content/seo/", import.meta.url).pathname;
const root = new URL("../", import.meta.url).pathname;
const files = readdirSync(dir).filter((f) => f.endsWith(".json")).sort();
const load = (f) => JSON.parse(readFileSync(join(dir, f), "utf8"));
const strip = (o) => { const rest = { ...o }; delete rest.needsVerification; return rest; };

// Search-result metadata for the category pages, written by hand rather than by the copywriter.
const CATEGORY_META = {
  "cad-software": {
    title: "CAD Software in India – AutoCAD, Revit, Fusion & More | Price & Buying Guide",
    description: "Compare CAD software in India: AutoCAD, AutoCAD LT, Civil 3D, Inventor and Fusion, with prices excluding GST and how to choose. Get a quote today.",
  },
  "bim-software": {
    title: "BIM Software in India – Revit, Revit LT, AEC Collection & Navisworks | Prices & Guide",
    description: "BIM software in India: Revit, Revit LT, the AEC Collection and Navisworks compared, with prices excluding GST and how to choose. Get a quote today.",
  },
  "pdf-software": {
    title: "PDF Software in India – Adobe Acrobat Pro & Standard | Price & Buying Guide",
    description: "PDF software for business in India: Adobe Acrobat Pro, Standard and Studio compared, with prices excluding GST and how to choose. Get a quote today.",
  },
  "firewall-security": {
    title: "Firewall Security in India – Fortinet, Sophos, SonicWall & Cisco | Quote & Guide",
    description: "Firewall security for Indian businesses: Fortinet, Sophos, SonicWall and Cisco compared, quoted on one purchase order with a GST invoice. Get a quote today.",
  },
  "business-laptops": {
    title: "Business Laptops in India – Lenovo, HP & Acer | Quote & Buying Guide",
    description: "Business laptops for Indian organisations: Lenovo, HP and Acer compared, quoted to your configuration and quantity with a GST invoice. Get a quote today.",
  },
  "backup-software": {
    title: "Backup Software in India – Acronis & Microsoft 365 Backup | Quote & Guide",
    description: "Backup software for Indian businesses: how to choose, what to protect and how Acronis is quoted, with a GST invoice from TechZoid. Get a quote today.",
  },
  "antivirus-endpoint-security": {
    title: "Antivirus & Endpoint Security in India – Kaspersky & Sophos | Quote & Guide",
    description: "Antivirus and endpoint security for Indian businesses: Kaspersky and Sophos compared, quoted per device with a GST invoice from TechZoid. Get a quote today.",
  },
  "video-editing-software": {
    title: "Video Editing Software in India – Premiere Pro, After Effects & Creative Cloud | Prices",
    description: "Video editing software in India: Premiere Pro, After Effects and Creative Cloud compared, with prices excluding GST. Get a quote today.",
  },
};

// Which brand hubs each category page links to.
const CATEGORY_BRANDS = {
  "firewall-security": ["fortinet", "sophos", "sonicwall", "cisco"],
  "business-laptops": ["lenovo", "hp", "acer"],
  "backup-software": ["acronis"],
  "antivirus-endpoint-security": ["kaspersky", "sophos"],
};
const replaces = JSON.parse(readFileSync(join(dir, "_replaces.json"), "utf8"));
const products = {}, categories = {}, posts = {}, refreshes = {}, brands = {};
for (const f of files) {
  const data = load(f);
  if (f.startsWith("product-")) products[data.slug] = strip(data);
  else if (f.startsWith("category-")) categories[data.slug] = { ...strip(data), ...(CATEGORY_META[data.slug] ?? {}), ...(CATEGORY_BRANDS[data.slug] ? { brands: CATEGORY_BRANDS[data.slug] } : {}) };
  else if (f.startsWith("brand-")) brands[data.slug] = strip(data);
  else if (f.startsWith("blog-")) posts[data.slug] = { ...strip(data), ...(replaces[data.slug] ? { replaces: replaces[data.slug] } : {}) };
  else if (f.startsWith("refresh-")) refreshes[data.slug] = strip(data);
}
const banner = "// Generated by scripts/build-seo-content.mjs from content/seo/*.json. Do not edit by hand.\n";
writeFileSync(join(root, "src/lib/content/product-guides.generated.ts"),
  `${banner}import type { ProductGuide } from "./guides";\n\nexport const PRODUCT_GUIDE_DATA: Record<string, ProductGuide> = ${JSON.stringify(products, null, 2)};\n`);
writeFileSync(join(root, "src/lib/content/category-guides.generated.ts"),
  `${banner}import type { CategoryGuide } from "./guides";\n\nexport const CATEGORY_GUIDE_DATA: Record<string, CategoryGuide> = ${JSON.stringify(categories, null, 2)};\n`);
writeFileSync(join(root, "src/lib/content/brand-guides.generated.ts"),
  `${banner}import type { BrandGuide } from "./guides";\n\nexport const BRAND_GUIDE_DATA: Record<string, BrandGuide> = ${JSON.stringify(brands, null, 2)};\n`);
writeFileSync(join(root, "prisma/content-migrations/seo-posts.generated.ts"),
  `${banner}export type SeoPost = { replaces?: { bodySha: string; faqSha: string }; slug: string; title: string; excerpt: string; category: string; tags: string[]; readMinutes: number; body: string; faqs: Array<{ question: string; answer: string }> };\nexport type SeoRefresh = { slug: string; newTitle: string; newExcerpt: string; appendBody: string; faqs: Array<{ question: string; answer: string }> };\n\nexport const SEO_POSTS: SeoPost[] = ${JSON.stringify(Object.values(posts), null, 2)};\n\nexport const SEO_REFRESHES: SeoRefresh[] = ${JSON.stringify(Object.values(refreshes), null, 2)};\n`);
console.log(`${Object.keys(products).length} product guides, ${Object.keys(categories).length} category pages, ${Object.keys(brands).length} brand hubs, ${Object.keys(posts).length} posts, ${Object.keys(refreshes).length} refreshes`);
